func TestItemTypeString(t *testing.T) {
	for _, tt := range itemStringCases() {
		if got := tt.value.String(); got != tt.want {
			t.Errorf("%T %d: String() = %q, want %q", tt.value, tt.value, got, tt.want)
		}
	}
}
